import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"Skills","description":"","frontmatter":{},"headers":[],"relativePath":"guides/skills.md","filePath":"guides/skills.md","lastUpdated":1792323081000}'),o={name:"guides/skills.md"};function l(n,e,r,d,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="skills" tabindex="-1">Skills <a class="header-anchor" href="#skills" aria-label="Permalink to &quot;Skills&quot;">​</a></h1><p>A <strong>Skill</strong> is a reusable prompt module that teaches a bot a fixed way of working: tone, procedure, tool habits. Skills have no dedicated management screen — a skill is a file in the workspace, and putting it in the right directory is all it takes to load.</p><div class="tip custom-block"><p class="custom-block-title">Limits</p><p>A session can request at most 5 skills at once; a single skill injects up to 64 KiB, 256 KiB total. These caps are not configurable.</p></div><h2 id="what-one-looks-like" tabindex="-1">What one looks like <a class="header-anchor" href="#what-one-looks-like" aria-label="Permalink to &quot;What one looks like&quot;">​</a></h2><p>A skill is a directory containing a <code>SKILL.md</code> with a YAML header — at minimum a stable <code>name</code> and a short <code>description</code>. The body is the instruction text actually injected for the agent:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">coder-skill</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Enables advanced coding workflows and tool usage.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Coder Skill</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Write clear code, explain trade-offs, and use the file/command tools when the task calls for them.</span></span></code></pre></div><p>Use plain ASCII names (<code>coder-skill</code>, <code>research</code>) without spaces — the name doubles as the directory name.</p><h2 id="which-directory-to-use" tabindex="-1">Which directory to use <a class="header-anchor" href="#which-directory-to-use" aria-label="Permalink to &quot;Which directory to use&quot;">​</a></h2><p>Put skills you write yourself in this directory of the bot&#39;s workspace:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/data/skills/user/personal/&lt;skill-name&gt;/SKILL.md</span></span></code></pre></div><p>Any way of getting the file there works: create it on the bot&#39;s <strong>Files</strong> tab, use the <strong>Terminal</strong>, or simply ask the bot — the workspace ships with a <code>skill-creator</code> skill, so describe the procedure you want and it writes the files to the right place.</p><p>You will see other directories, but <strong>don&#39;t put files there by hand</strong>:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Owned by</th></tr></thead><tbody><tr><td><code>/data/skills/user/personal/</code></td><td><strong>You.</strong> All hand-written skills go here</td></tr><tr><td><code>/data/skills/&lt;registry&gt;/&lt;app&gt;/</code></td><td><a href="./supermarket.html">Apps</a>. Installed, updated, and removed with the App — don&#39;t edit</td></tr><tr><td><code>/data/.memoh/skills/</code></td><td>Built-in skills from the workspace template (such as <code>skill-creator</code>). Refreshed to the template version on every workspace init, so edits get overwritten; to customize, copy it under a new name into your own directory</td></tr><tr><td><code>/data/.skills/</code>, <code>/data/.agents/skills/</code></td><td>Legacy compatibility paths, discovery only — don&#39;t add new files</td></tr></tbody></table><h2 id="same-name-multiple-copies" tabindex="-1">Same name, multiple copies <a class="header-anchor" href="#same-name-multiple-copies" aria-label="Permalink to &quot;Same name, multiple copies&quot;">​</a></h2><p><strong>The skill name is its identity</strong>: however many directories a name appears in, only one copy is effective at a time. A skill in your own directory takes precedence over one in a legacy path. To change how an App&#39;s skill behaves, don&#39;t edit its files — write your own version under a new name.</p><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><ol><li>Keep them few and sharp, with a clear <code>name</code> and <code>description</code> — the agent decides whether to load a skill from its description.</li><li>Only recurring procedures are worth turning into skills; one-off requirements can just be said in chat.</li><li>Prefer installing from the <a href="./supermarket.html">Supermarket</a> over copy-pasting duplicates.</li></ol>`,17)])])}const m=t(o,[["render",l]]);export{k as __pageData,m as default};
